mapper.insert:
insert into CUS_HR_BIRTH_LEAVE (ID, PLO_NUM, LABEL_ID, 
  LABEL_NAME, BEG_DATE, END_DATE, 
  MODIFY_ID, MODIFY_TIME, GROUP_ID
  )
values (#{id,jdbcType=VARCHAR}, #{ploNum,jdbcType=VARCHAR}, #{labelId,jdbcType=DECIMAL}, 
  #{labelName,jdbcType=VARCHAR}, #{begDate,jdbcType=VARCHAR}, #{endDate,jdbcType=VARCHAR}, 
  #{modifyId,jdbcType=VARCHAR}, #{modifyTime,jdbcType=VARCHAR}, #{groupId,jdbcType=DECIMAL}
  )

mapper.select:
SELECT a.PLO_NUM, a.GROUP_ID, b.LABEL_ID, b.LABEL_NAME, b.BEG_DATE, b.END_DATE FROM ( SELECT PLO_NUM, max( group_id ) group_id FROM CUS_HR_BIRTH_LEAVE
where PLO_NUM = #{ploNum,jdbcType=VARCHAR}
GROUP BY PLO_NUM ) a LEFT JOIN ( SELECT * FROM CUS_HR_BIRTH_LEAVE WHERE to_char( SYSDATE, 'yyyy-MM-dd' ) BETWEEN nvl( BEG_DATE, '2999-12-12' ) AND nvl( END_DATE, '2999-12-12' ) ORDER BY LABEL_ID DESC ) b ON ( a.PLO_NUM = b.PLO_NUM)
